    { type: "short", q: "What percentage of the world's territories had fallen under colonial rule by the outbreak of the First World War in 1914?", answer: "about 85 percent|85 percent", difficulty: 2, explanation: "When the First World War broke out in 1914, about 85 percent of the territories in the world were under colonial rule." },
    { type: "ordering", q: "Arrange these developments in the correct chronological order.", options: ["Berlin Conference of 1884-85", "Abolition of the slave trade", "Scramble for Africa in the 1870s and 1880s", "Industrial Revolution and the Legitimate Trade"], answer: 3, difficulty: 3, explanation: "The order is: Industrial Revolution and the Legitimate Trade, abolition, the Scramble for Africa, then the Berlin Conference." }
